import { describe, expect, it } from "vitest";
import { TrackerResponseDataSchema } from "./conversation";

describe("TrackerResponseDataSchema", () => {
  it("drops a malformed skill_state but keeps the rest of the payload", () => {
    const parsed = TrackerResponseDataSchema.parse({
      sender_id: "sender-1",
      events: [{ event: "user", timestamp: 1712000000 }],
      slots: { account_type: "premium" },
      stack: [{ frame_id: "f1", flow_id: "card_replace", step_id: "start" }],
      skill_state: { blocks: "nonsense" },
    });

    expect(parsed.skill_state).toBeUndefined();
    expect(parsed.sender_id).toBe("sender-1");
    expect(parsed.events).toHaveLength(1);
    expect(parsed.slots).toEqual({ account_type: "premium" });
    expect(parsed.stack).toEqual([{ frame_id: "f1", flow_id: "card_replace", step_id: "start" }]);
  });
});
